mapper.update:
/*updateMasterMpIfOrderCreate*/

		UPDATE IF_PODT_EXUP 
		SET AGENT             = #{AGENT}
		  , CONTRACT_NO       = #{CONTRACT_NO}
		  , CONTRACT_SEQ      = #{CONTRACT_SEQ}
		  , PURCHASER_USER_ID = #{PURCHASER_USER_ID}
		  , PO_DATE          = #{PO_DATE}
		  , RD_DATE           = #{RD_DATE}
		  , BUYER_ITEM_NO     = NVL(TRIM(#{BUYER_ITEM_NO}),' ')
		  , UNIT_PRICE        = NVL(#{UNIT_PRICE_IF},UNIT_PRICE)
		  , ITEM_AMT          = NVL(#{UNIT_PRICE_IF},UNIT_PRICE) * ITEM_QTY
		  , DELY_TO_LOCATION  = #{DELY_TO_LOCATION}
		  , DELY_TO_LOCATION_TEXT  = #{DELY_TO_LOCATION_TEXT}
		  , BUDGET_ACCOUNT 	  = #{BUDGET_ACCOUNT_CODE}
		  , BUDGET_DEPT		  = #{BUDGET_DEPT_CODE}
		  , REQ_USER_INFO     = #{REQ_USER_INFO}
		  , REMARK   		  = #{REMARK}
		  , LEGACY_PR_NO	  = #{LEGACY_PR_NO}
		WHERE 1=1
		AND BUYER             = #{BUYER}
		AND LEGACY_PO_NO      = NVL(#{LEGACY_PO_NO},' ')
		AND LEGACY_PO_SEQ     = NVL(#{LEGACY_PO_SEQ},' ')
		AND ADD_USER_ID		  = NVL(#{st_user_id},' ')
		AND DOC_TYPE = 'CREATE'

/*updateMasterMpIfOrderFlagNErrormsg*/

		UPDATE IF_PODT_EXUP 
		SET IF_FLAG = #{IF_FLAG}
		  , ERROR_MSG = #{ERROR_MSG}
		WHERE 1=1
		AND BUYER             = #{BUYER}
		AND LEGACY_PO_NO      = NVL(#{LEGACY_PO_NO},' ')
		AND LEGACY_PO_SEQ     = NVL(#{LEGACY_PO_SEQ},' ')
		AND ADD_USER_ID		  = NVL(#{st_user_id},' ')
		AND DOC_TYPE = 'CREATE'


/*deleteMasterMpIfOrderCreate*/
DELETE FROM IF_PODT_EXUP
      WHERE BUYER = #{BUYER}
        AND LEGACY_PO_NO = #{LEGACY_PO_NO}
        AND LEGACY_PO_SEQ = #{LEGACY_PO_SEQ}
        AND ADD_USER_ID = #{st_user_id}
        AND DOC_TYPE = 'CREATE'


/*executeMasterMpIfOrderCreate*/
INSERT INTO ICOMTRXL(DOC_NAME, TARGET, KEY_1, KEY_2, KEY_3, KEY_4, KEY_5, KEY_6, KEY_7, KEY_8, KEY_9, KEY_10)
			  VALUES('PO_EXUP',#{st_user_id},#{st_buyer_code},' ',' ',' ',' ',' ',' ',' ',' ',' ')


	/*updateMasterMpIfOrderFlag*/
	UPDATE IF_PODT_EXUP
	   SET IF_FLAG = 'T'
     WHERE BUYER = #{st_buyer_code}
       AND ADD_USER_ID = #{st_user_id}

